import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Metatrader 5","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/metatrader-5/index.md","filePath":"trading-platform/metatrader-5/index.md"}'),d={name:"trading-platform/metatrader-5/index.md"};function n(i,e,s,l,c,h){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="metatrader-5" tabindex="-1">Metatrader 5 <a class="header-anchor" href="#metatrader-5" aria-label="Permalink to &quot;Metatrader 5&quot;">​</a></h1><p>MetaTrader 5 is widely used for charting and for running Expert Advisors, but its built-in trading functions talk to a forex or CFD broker, not to an Indian broker. The Tradeboard MQL5 library bridges that gap: your EA keeps generating signals in MetaTrader, and every order is routed over HTTP to your Tradeboard instance, which forwards it to whichever of the supported brokers you have connected.</p><p><strong>How it fits together</strong></p><p>The library is a set of MQL5 include files that you drop into <code>MQL5\\Include\\Tradeboard</code>. It exposes six functions (<code>PlaceOrder</code>, <code>PlaceSmartOrder</code>, <code>ModifyOrder</code>, <code>CancelOrder</code>, <code>ClosePosition</code>, <code>CancelAllOrders</code>) that POST JSON to the matching <code>/api/v1/</code> endpoints on your Tradeboard server. Nothing runs inside MetaTrader beyond the HTTP call, so the broker connection, symbol mapping, analyzer mode, logging and rate limiting all stay in Tradeboard.</p><p>Requests go out through <code>wininet.dll</code>, which means the EA needs <strong>Allow DLL imports</strong> enabled. It also means MQL5&#39;s <code>WebRequest()</code> URL allowlist is not used, so there is nothing to configure under Tools, Options, Expert Advisors, Allow WebRequest.</p><p><strong>What the library covers</strong></p><ul><li>Order placement, including smart orders that reconcile against your live position</li><li>Order modification and cancellation</li><li>Closing all positions or cancelling all orders for a strategy</li></ul><p>Market data, the order book, the position book and holdings are not wrapped. Call the Tradeboard REST API directly if your EA needs them.</p><p><strong>Before you start</strong></p><ul><li>Tradeboard installed, running and logged in to your broker</li><li>An Tradeboard API key from the API Key page of the dashboard</li><li>The URL where MetaTrader can reach Tradeboard, typically <code>http://127.0.0.1:5000</code> when both run on the same Windows machine</li><li>Symbols written in the Tradeboard format: <code>SBIN</code> for equities (no <code>-EQ</code> suffix), <code>NIFTY30JAN25FUT</code> for futures, <code>NIFTY30JAN2521500CE</code> for options</li></ul><p>The pages that follow walk through installing the library, including the header, the functions it provides, and a complete EMA crossover Expert Advisor.</p>',11)])])}const g=o(d,[["render",n]]);export{u as __pageData,g as default};
